package dev.admutium.techmod.test;
import dev.admutium.techmod.TechMod;
import dev.admutium.techmod.material.*;
import dev.admutium.techmod.machine.*;
import dev.admutium.techmod.storage.*;
import dev.admutium.techmod.conveyor.*;
import dev.admutium.techmod.energy.Energy;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.HopperBlockEntity;
import net.minecraft.world.phys.*;
import java.util.*;
public final class MaterialsGameTests {
 private CraftingInput grid(ItemStack... stacks){return CraftingInput.of(3,3,java.util.stream.IntStream.range(0,9).mapToObj(i->i<stacks.length?stacks[i]:ItemStack.EMPTY).toList());}
 private MachineBlockEntity machine(GameTestHelper h,MachineKind kind,BlockPos p){h.setBlock(p,Machines.BLOCKS.get(kind));return h.getBlockEntity(p,MachineBlockEntity.class);}
 @GameTest public void hammerProducesAllMetalPlatesInstantlyAndWearsOnce(GameTestHelper h){var recipe=new ManualRecipe();for(var e:Machines.PLATES.entrySet()){if(e.getKey()==Materials.ROOTS)continue;var tool=new ItemStack(Materials.HAMMER);tool.setDamageValue(17);var input=grid(tool,new ItemStack(e.getKey()));h.assertTrue(recipe.matches(input,h.getLevel())&&recipe.assemble(input).is(e.getValue()),"Manual plate recipe missing");var left=recipe.getRemainingItems(input);h.assertTrue(left.get(0).is(Materials.HAMMER)&&left.get(0).getDamageValue()==18&&tool.getDamageValue()==17,"Tool damaged original input or wore incorrectly");}h.succeed();}
 @GameTest public void thirtySecondHammerOperationBreaksWithoutLosingOutput(GameTestHelper h){var tool=new ItemStack(Materials.HAMMER);tool.setDamageValue(31);var input=grid(new ItemStack(Items.IRON_INGOT),tool);var recipe=new ManualRecipe();h.assertTrue(recipe.matches(input,h.getLevel())&&recipe.assemble(input).getCount()==1&&recipe.getRemainingItems(input).get(1).isEmpty(),"Last hammer craft has wrong output or indestructible remainder");h.succeed();}
 @GameTest public void rootsNeedTwoCraftingCellsAndDoNotAcceptStackCountShortcut(GameTestHelper h){var recipe=new ManualRecipe();var bad=grid(new ItemStack(Materials.HAMMER),new ItemStack(Materials.ROOTS,2));var good=grid(new ItemStack(Materials.HAMMER),new ItemStack(Materials.ROOTS),new ItemStack(Materials.ROOTS));h.assertTrue(!recipe.matches(bad,h.getLevel())&&recipe.matches(good,h.getLevel())&&recipe.assemble(good).is(Materials.CAOUTCHOUC),"Root input quantity is ambiguous or exploitable");h.succeed();}
 @GameTest public void manualRecipesRejectExtraToolsAndUnrelatedItems(GameTestHelper h){var r=new ManualRecipe();h.assertTrue(!r.matches(grid(new ItemStack(Materials.HAMMER),new ItemStack(Materials.HAMMER),new ItemStack(Items.IRON_INGOT)),h.getLevel())&&!r.matches(grid(new ItemStack(Materials.CUTTERS),new ItemStack(Materials.ROOTS)),h.getLevel()),"Invalid processing recipe accepted");h.succeed();}
 @GameTest public void cutterAndManualCuttersHaveIdenticalYield(GameTestHelper h){var plate=Machines.PLATES.get(Items.COPPER_INGOT);var input=grid(new ItemStack(Materials.CUTTERS),new ItemStack(plate));var manual=new ManualRecipe().assemble(input);var m=machine(h,MachineKind.CUTTER,new BlockPos(2,1,2));m.energy=Energy.BUFFER;m.setItem(0,new ItemStack(plate));for(int i=0;i<80;i++){m.beginTick();m.finishTick();}h.assertTrue(manual.is(Materials.COPPER_WIRE)&&manual.getCount()==4&&ItemStack.matches(manual,m.getItem(1))&&m.energy==292*Energy.UNIT,"Cutter output, time or energy differs from agreed economy");h.succeed();}
 @GameTest public void cutterDoesNotConsumeIngotsOrFullOutput(GameTestHelper h){var m=machine(h,MachineKind.CUTTER,new BlockPos(2,1,2));m.energy=Energy.BUFFER;m.setItem(0,new ItemStack(Items.COPPER_INGOT));for(int i=0;i<100;i++){m.beginTick();m.finishTick();}h.assertTrue(m.energy==Energy.BUFFER&&m.getItem(1).isEmpty(),"Cutter accepts ingots");m.setItem(0,new ItemStack(Machines.PLATES.get(Items.COPPER_INGOT)));m.setItem(1,new ItemStack(Materials.COPPER_WIRE,61));for(int i=0;i<100;i++){m.beginTick();m.finishTick();}h.assertTrue(m.energy==Energy.BUFFER&&m.getItem(0).getCount()==1,"Blocked cutter wastes material or energy");h.succeed();}
 @GameTest public void pressRootAndTinRecipesKeepEightTECost(GameTestHelper h){var m=machine(h,MachineKind.PRESS,new BlockPos(2,1,2));for(var pair:List.of(Map.entry(Materials.ROOTS,Materials.CAOUTCHOUC),Map.entry(Materials.TIN_INGOT,Materials.TIN_PLATE))){m.setItem(0,new ItemStack(pair.getKey()));m.setItem(1,ItemStack.EMPTY);m.energy=Energy.BUFFER;for(int i=0;i<80;i++){m.beginTick();m.finishTick();}h.assertTrue(m.getItem(1).is(pair.getValue())&&m.energy==292*Energy.UNIT,"Press conversion missing or wrong cost");}h.succeed();}
 @GameTest public void tinCrushingAndSmeltingDoubleYieldWithoutChangingCosts(GameTestHelper h){var crusher=machine(h,MachineKind.CRUSHER,new BlockPos(2,1,2));crusher.energy=Energy.BUFFER;crusher.setItem(0,new ItemStack(Materials.RAW_TIN));for(int i=0;i<120;i++){crusher.beginTick();crusher.finishTick();}h.assertTrue(crusher.getItem(1).is(Materials.CRUSHED_TIN)&&crusher.getItem(1).getCount()==2&&crusher.energy==288*Energy.UNIT,"Tin crushing economy wrong");var furnace=machine(h,MachineKind.FURNACE,new BlockPos(4,1,2));furnace.energy=Energy.BUFFER;furnace.setItem(0,crusher.getItem(1).copy());for(int i=0;i<320;i++){furnace.beginTick();furnace.finishTick();}h.assertTrue(furnace.getItem(1).is(Materials.TIN_INGOT)&&furnace.getItem(1).getCount()==2&&furnace.energy==268*Energy.UNIT,"Tin smelting yield/cost wrong");h.succeed();}
 @GameTest public void vanillaRecipesLoadAndInsulationRequiresCrossPattern(GameTestHelper h){var w=h.getLevel();var cross=grid(ItemStack.EMPTY,new ItemStack(Materials.COPPER_WIRE),ItemStack.EMPTY,new ItemStack(Materials.COPPER_WIRE),new ItemStack(Materials.RUBBER),new ItemStack(Materials.COPPER_WIRE),ItemStack.EMPTY,new ItemStack(Materials.COPPER_WIRE));var result=w.recipeAccess().getRecipeFor(RecipeType.CRAFTING,cross,w).orElseThrow().value().assemble(cross);h.assertTrue(result.is(TechMod.COPPER_CABLE)&&result.getCount()==4,"Insulation recipe missing or wrong count");var smelt=w.recipeAccess().getRecipeFor(RecipeType.SMELTING,new SingleRecipeInput(new ItemStack(Materials.CAOUTCHOUC)),w).orElseThrow();h.assertTrue(smelt.value().assemble(new SingleRecipeInput(new ItemStack(Materials.CAOUTCHOUC))).is(Materials.RUBBER),"Caoutchouc furnace recipe missing");h.succeed();}
 @GameTest public void immatureDandelionDropsNothingAndMatureAlwaysHasRootsAndSeeds(GameTestHelper h){var p=h.absolutePos(new BlockPos(2,1,2));var w=h.getLevel();for(int age=0;age<7;age++)h.assertTrue(Block.getDrops(Materials.CROP.getStateForAge(age),w,p,null).isEmpty(),"Immature plant drops items");for(int i=0;i<30;i++){var drops=Block.getDrops(Materials.CROP.getStateForAge(7),w,p,null);int roots=0,seeds=0;for(var s:drops){if(s.is(Materials.ROOTS))roots+=s.getCount();if(s.is(Materials.SEEDS))seeds+=s.getCount();}h.assertTrue(roots==1&&(seeds==1||seeds==2),"Mature crop loot wrong");}h.succeed();}
 @GameTest public void dandelionBonusSeedChanceIsApproximatelySixtyPercent(GameTestHelper h){var p=h.absolutePos(new BlockPos(2,1,2));int bonus=0;for(int i=0;i<400;i++){int seeds=Block.getDrops(Materials.CROP.getStateForAge(7),h.getLevel(),p,null).stream().filter(s->s.is(Materials.SEEDS)).mapToInt(ItemStack::getCount).sum();bonus+=seeds-1;}h.assertTrue(bonus>185&&bonus<295,"Bonus seed distribution is not 60 percent");h.succeed();}
 @GameTest public void seedsGrowOnFarmlandAndWildAdultsSurviveOnGrass(GameTestHelper h){var w=h.getLevel();var p=h.absolutePos(new BlockPos(2,1,2));w.setBlock(p.below(),Blocks.GRASS_BLOCK.defaultBlockState(),3);h.assertTrue(Materials.CROP.getStateForAge(7).canSurvive(w,p)&&!Materials.CROP.getStateForAge(0).canSurvive(w,p),"Seeds can be planted directly on grass or wild mature plant dies");w.setBlock(p.below(),Blocks.FARMLAND.defaultBlockState(),3);h.assertTrue(Materials.CROP.getStateForAge(0).canSurvive(w,p),"Seed cannot survive on farmland");h.succeed();}
 @GameTest public void realHopperBelowCutterOnlyTakesFinishedWire(GameTestHelper h){var r=new BlockPos(2,2,2);var m=machine(h,MachineKind.CUTTER,r);m.setItem(0,new ItemStack(Machines.PLATES.get(Items.COPPER_INGOT),7));m.setItem(1,new ItemStack(Materials.COPPER_WIRE,4));m.setItem(2,new ItemStack(Machines.BATTERY));h.setBlock(r.below(),Blocks.HOPPER);var hopper=h.getBlockEntity(r.below(),HopperBlockEntity.class);for(int i=0;i<12;i++)HopperBlockEntity.suckInItems(h.getLevel(),hopper);int count=0;for(var s:hopper){h.assertTrue(s.isEmpty()||s.is(Materials.COPPER_WIRE),"Hopper stole input or battery");count+=s.getCount();}h.assertTrue(count==4&&m.getItem(0).getCount()==7&&!m.getItem(2).isEmpty(),"Finished product not extracted exclusively");h.succeed();}
 @GameTest public void hopperBelowGeneratorCannotStealCoalOrBattery(GameTestHelper h){var r=new BlockPos(2,2,2);var m=machine(h,MachineKind.GENERATOR,r);m.setItem(0,new ItemStack(Items.COAL,12));m.setItem(1,new ItemStack(Machines.BATTERY));h.setBlock(r.below(),Blocks.HOPPER);var hopper=h.getBlockEntity(r.below(),HopperBlockEntity.class);h.assertTrue(!HopperBlockEntity.suckInItems(h.getLevel(),hopper)&&hopper.isEmpty(),"Hopper steals coal or charging battery");h.succeed();}
 @GameTest public void reinforcedChestHasThirtySixRealSlotsAndGhostSampleCannotDuplicate(GameTestHelper h){var r=new BlockPos(2,1,2);h.setBlock(r,ReinforcedStorage.BLOCK);var chest=h.getBlockEntity(r,ReinforcedChestEntity.class);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(chest.getBlockPos().getX()+.5,chest.getBlockPos().getY(),chest.getBlockPos().getZ()+.5);var menu=new ReinforcedChestMenu(1,player.getInventory(),chest);menu.setCarried(new ItemStack(Materials.TIN_INGOT,17));menu.clicked(36,0,net.minecraft.world.inventory.ContainerInput.PICKUP,player);h.assertTrue(chest.getContainerSize()==36&&chest.sample.getItem(0).getCount()==1&&menu.getCarried().getCount()==17,"Sample consumed item or became storage");h.assertTrue(menu.quickMoveStack(player,36).isEmpty(),"Ghost sample extractable");menu.clicked(36,1,net.minecraft.world.inventory.ContainerInput.PICKUP,player);h.assertTrue(chest.sample.isEmpty()&&menu.getCarried().getCount()==17,"Clear sample changes inventory");menu.removed(player);h.succeed();}
 @GameTest public void tinNeedsStonePickaxeAndDriveEmitsNoLight(GameTestHelper h){for(var b:List.of(Materials.TIN_ORE,Materials.DEEPSLATE_TIN_ORE)){h.assertTrue(!new ItemStack(Items.WOODEN_PICKAXE).isCorrectToolForDrops(b.defaultBlockState())&&new ItemStack(Items.STONE_PICKAXE).isCorrectToolForDrops(b.defaultBlockState()),"Wrong tin harvest tier");}h.assertTrue(Machines.BLOCKS.get(MachineKind.DRIVE).defaultBlockState().setValue(MachineBlock.ACTIVE,true).getLightEmission()==0,"Drive emits world light");h.succeed();}
 @GameTest public void continuingFromRampTargetsItsOutputAndKeepsDirection(GameTestHelper h){var w=h.getLevel();var root=h.absolutePos(new BlockPos(3,2,3));var state=Conveyors.BLOCKS.get(Conveyors.Kind.BELT).defaultBlockState().setValue(ConveyorBlock.FACING,Direction.EAST).setValue(ConveyorBlock.SLOPE,2);w.setBlock(root,state,3);w.setBlock(root.below(),state.setValue(ConveyorBlock.UPPER,true),3);var player=h.makeMockPlayer(GameType.CREATIVE);var stack=new ItemStack(Conveyors.ITEMS.get(Conveyors.Kind.BELT));var hit=new BlockHitResult(Vec3.atCenterOf(root),Direction.UP,root,false);var context=ConveyorItem.placementContext(new net.minecraft.world.item.context.BlockPlaceContext(player,InteractionHand.MAIN_HAND,stack,hit));h.assertTrue(context.getClickedPos().equals(root.east().below()),"Descent continuation aimed at wrong height");var next=Conveyors.BLOCKS.get(Conveyors.Kind.BELT).getStateForPlacement(context);h.assertTrue(next!=null&&next.getValue(ConveyorBlock.FACING)==Direction.EAST,"Continuation follows camera instead of line");h.succeed();}

 @GameTest public void tinLootSupportsSilkTouchAndFortune(GameTestHelper h){var w=h.getLevel();var pos=h.absolutePos(new BlockPos(2,1,2));var silk=new ItemStack(Items.IRON_PICKAXE);silk.enchant(w.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.SILK_TOUCH),1);var fortune=new ItemStack(Items.IRON_PICKAXE);fortune.enchant(w.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.FORTUNE),3);
  for(var ore:List.of(Materials.TIN_ORE,Materials.DEEPSLATE_TIN_ORE)){var drops=Block.getDrops(ore.defaultBlockState(),w,pos,null,null,silk);h.assertTrue(drops.size()==1&&drops.getFirst().is(ore.asItem()),"Silk touch did not preserve tin ore variant");int n=0;for(int k=0;k<32;k++)n+=Block.getDrops(ore.defaultBlockState(),w,pos,null,null,fortune).stream().filter(a->a.is(Materials.RAW_TIN)).mapToInt(ItemStack::getCount).sum();h.assertTrue(n>32,"Fortune has no effect on raw tin");}h.succeed();}
 @GameTest public void reinforcedChestSavesContentsAndDisplayAndDropsNoGhost(GameTestHelper h){var rel=new BlockPos(3,1,3);h.setBlock(rel,ReinforcedStorage.BLOCK);var be=h.getBlockEntity(rel,ReinforcedChestEntity.class);be.setItem(35,new ItemStack(Items.DIAMOND,13));be.sample.setItem(0,new ItemStack(Materials.TIN_INGOT));var w=h.getLevel();var tag=be.saveCustomOnly(w.registryAccess());var restored=new ReinforcedChestEntity(be.getBlockPos(),be.getBlockState());restored.loadCustomOnly(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,w.registryAccess(),tag));h.assertTrue(restored.getItem(35).getCount()==13&&restored.sample.getItem(0).is(Materials.TIN_INGOT),"Chest did not persist last row or display");w.destroyBlock(be.getBlockPos(),true);int diamonds=0,ghosts=0,chests=0;for(var e:w.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(be.getBlockPos()).inflate(2))){var item=e.getItem();if(item.is(Items.DIAMOND))diamonds+=item.getCount();if(item.is(Materials.TIN_INGOT))ghosts+=item.getCount();if(item.is(ReinforcedStorage.ITEM))chests+=item.getCount();}h.assertTrue(diamonds==13&&ghosts==0&&chests==1,"Breaking chest lost/duplicated contents or spawned ghost sample");h.succeed();}

 @GameTest public void generatedDandelionPatchIsThreeToSixMaturePlantsInsideOneChunk(GameTestHelper h){var w=h.getLevel();var near=h.absolutePos(new BlockPos(500,100,500));int x0=(near.getX()>>4)<<4,z0=(near.getZ()>>4)<<4,y=near.getY();
  try{for(int x=0;x<16;x++)for(int z=0;z<16;z++)w.setBlock(new BlockPos(x0+x,y,z0+z),Blocks.GRASS_BLOCK.defaultBlockState(),2);
   var feature=w.registryAccess().lookupOrThrow(Registries.FEATURE).getOrThrow(net.minecraft.resources.ResourceKey.create(Registries.FEATURE,TechMod.id("dandelion_patch"))).value();h.assertTrue(feature.place(w,w.getChunkSource().getGenerator(),net.minecraft.util.RandomSource.create(19),new BlockPos(x0+8,y+1,z0+8)),"Registered wild patch did not generate");int n=0;for(int x=0;x<16;x++)for(int z=0;z<16;z++){var state=w.getBlockState(new BlockPos(x0+x,y+1,z0+z));if(state.is(Materials.CROP)){n++;h.assertTrue(Materials.CROP.isMaxAge(state),"Wild plant is immature");}}h.assertTrue(n>=3&&n<=6,"Wild patch size outside 3–6");
  }finally{for(int x=0;x<16;x++)for(int z=0;z<16;z++){w.removeBlock(new BlockPos(x0+x,y+1,z0+z),false);w.removeBlock(new BlockPos(x0+x,y,z0+z),false);}}h.succeed();}
 @GameTest public void registeredTinOreFeatureReplacesStoneAndDeepslate(GameTestHelper h){var w=h.getLevel();var p=h.absolutePos(new BlockPos(600,100,600));
  try{for(int x=0;x<16;x++)for(int y=-4;y<=3;y++)for(int z=0;z<16;z++)w.setBlock(p.offset(x,y,z),(z<8?Blocks.STONE:Blocks.DEEPSLATE).defaultBlockState(),2);
   var feature=w.registryAccess().lookupOrThrow(Registries.FEATURE).getOrThrow(net.minecraft.resources.ResourceKey.create(Registries.FEATURE,TechMod.id("tin_ore"))).value();var chunks=new java.util.HashSet<net.minecraft.world.level.chunk.LevelChunk>();for(int x:new int[]{0,15})for(int z:new int[]{0,15})chunks.add(w.getChunkAt(p.offset(x,0,z)));for(var chunk:chunks)net.minecraft.world.level.levelgen.Heightmap.primeHeightmaps(chunk,java.util.EnumSet.of(net.minecraft.world.level.levelgen.Heightmap.Types.OCEAN_FLOOR_WG));for(int k=0;k<16;k++)feature.place(w,w.getChunkSource().getGenerator(),net.minecraft.util.RandomSource.create(k),p.offset(8,0,8));int stone=0,deep=0;for(int x=0;x<16;x++)for(int y=-4;y<=3;y++)for(int z=0;z<16;z++){var s1=w.getBlockState(p.offset(x,y,z));if(s1.is(Materials.TIN_ORE))stone++;if(s1.is(Materials.DEEPSLATE_TIN_ORE))deep++;}h.assertTrue(stone>0&&deep>0,"Tin feature did not generate both host variants: "+stone+" / "+deep);
  }finally{for(int x=0;x<16;x++)for(int y=-4;y<=3;y++)for(int z=0;z<16;z++)w.removeBlock(p.offset(x,y,z),false);}h.succeed();}
}
